import * as THREE from 'three'
import React, { forwardRef, useMemo, useRef } from 'react'
import { useLoader, useUpdate, useFrame } from 'react-three-fiber'
import { MASCOT_TYPEFACE_URL } from './mascotAssets'
import { TEXTURE_PRESETS, applyStateTint } from './mascotMaterials'
import { kelvinGradientShader, pbrSurfaceShader } from './mascotShaders'
import { mergeVerticesWithThree } from './geometryUtils'
import { poolLightDirAt } from './kelvinColor'

const MascotText = forwardRef(
  ({ children, size = 5, visualRef, poolIntensityRef, poolColorRef, poolSpreadRef, textureKey = 'microcement', envMapRef, keylightRef, mascotWorldPosRef }, ref) => {
    const font = useLoader(THREE.FontLoader, MASCOT_TYPEFACE_URL)
    const shaderRef = useRef()
    const poolLight = useRef(new THREE.Color())
    const preset = TEXTURE_PRESETS[textureKey] || TEXTURE_PRESETS.microcement
    const midColor = useRef(new THREE.Color())
    const poolDir = useRef(new THREE.Vector3(0, -1, 0.12))

    const shaderDef = useMemo(
      () => (preset.type === 'shader' ? kelvinGradientShader : pbrSurfaceShader),
      [textureKey, preset.type]
    )

    const uniforms = useMemo(() => THREE.UniformsUtils.clone(shaderDef.uniforms), [shaderDef])

    const config = useMemo(
      () => ({
        font,
        size: 40,
        height: 42,
        curveSegments: 200,
        bevelEnabled: true,
        bevelThickness: 1.0,
        bevelSize: 0.55,
        bevelSegments: 80
      }),
      [font]
    )

    const mesh = useUpdate(
      self => {
        const geom = self.geometry
        if (!geom?.attributes?.position) return
        if (geom.userData._prepared) return

        geom.computeBoundingBox()
        if (!geom.boundingBox) return
        const center = new THREE.Vector3()
        geom.boundingBox.getCenter(center)
        geom.translate(-center.x, -center.y, -center.z)

        let finalGeom = geom
        try {
          if (geom.attributes.position.count > 0) {
            finalGeom = mergeVerticesWithThree(THREE, geom, 1e-4)
            if (finalGeom !== geom) geom.dispose()
          }
        } catch (err) {
          finalGeom = geom
        }

        finalGeom.computeVertexNormals()
        finalGeom.userData._prepared = true
        if (finalGeom !== self.geometry) self.geometry = finalGeom
      },
      [children]
    )

    useFrame(() => {
      if (!shaderRef.current || !visualRef?.current) return
      const v = visualRef.current
      const poolScale = poolIntensityRef?.current ?? 0.62
      const u = shaderRef.current.uniforms

      if (poolColorRef?.current) poolLight.current.copy(poolColorRef.current)
      else poolLight.current.set(v.light)

      if (mascotWorldPosRef?.current) {
        poolLightDirAt(mascotWorldPosRef.current, poolDir.current)
        u.lightDir.value.copy(poolDir.current)
      }

      if (preset.type === 'shader') {
        const hot = new THREE.Color(v.colorA)
        const cool = new THREE.Color(v.colorB)
        midColor.current.copy(hot).lerp(cool, 0.52)
        u.colorHot.value.copy(hot)
        u.colorMid.value.copy(midColor.current)
        u.colorCool.value.copy(cool)
        u.lightColor.value.copy(poolLight.current)
        u.lightIntensity.value = poolScale * v.lightIntensity * 0.85
        u.bodyDim.value = v.bodyDim ?? 0.68
        return
      }

      const tintSource = `#${poolLight.current.getHexString()}`
      const tint = applyStateTint(preset.color || '#ffffff', tintSource, preset.stateTint ?? 0.2)
      u.baseColor.value.copy(tint)
      u.lightColor.value.copy(poolLight.current)
      u.lightIntensity.value = poolScale * v.lightIntensity * 0.85
      u.metalness.value = preset.metalness ?? 0.5
      u.roughness.value = preset.roughness ?? 0.5
      u.clearcoat.value = preset.clearcoat ?? 0
      u.clearcoatRoughness.value = preset.clearcoatRoughness ?? 0.1
      u.envMap.value = envMapRef?.current || null
      u.envMapIntensity.value = preset.envMapIntensity ?? 1
      u.lightPickup.value = preset.lightPickup ?? 0.5
      u.poolSpread.value = poolSpreadRef?.current ?? 0.52
      if (keylightRef?.current) {
        u.keyLightDir.value.copy(keylightRef.current.dir)
        u.keyLightColor.value.copy(keylightRef.current.color)
        u.keyLightIntensity.value = keylightRef.current.intensity
      }
    })

    return (
      <group ref={ref} scale={[0.1 * size, 0.1 * size, 0.1]}>
        <mesh ref={mesh}>
          <textGeometry attach="geometry" args={[children, config]} />
          <shaderMaterial
            key={textureKey}
            ref={shaderRef}
            attach="material"
            args={[{ ...shaderDef, uniforms, extensions: shaderDef.extensions || {} }]}
          />
        </mesh>
      </group>
    )
  }
)

export default MascotText
